      what: 'Состав недели: 7 дней без пропусков, пропорция задач (объяснить — дважды, остальные по одному разу), отсутствие повторов рубрик и форматов два дня подряд, продающая публикация не первая.',
      stop: 'Если нарушена пропорция задач или план начинается с продающей публикации — план возвращается на перегенерацию, дальше не идёт.',
    },
    {
      stage: 'После написания текстов',
      what: 'Объём под площадку (Telegram до 900 символов, ВКонтакте до 1400), различимость версий, хэштеги и вопрос к читателю только во ВКонтакте, отсутствие запрещённых формулировок.',
      stop: 'Если в тексте появилась гарантия результата, срочность, сравнение с конкурентами или медицинское обещание — материал останавливается и переписывается целиком.',
    },
    {
      stage: 'Перед постановкой в расписание',
      what: 'Сверка темы с журналом публикаций за последние две недели: смысл не должен повторяться. Проверка, что у каждой записи есть дата, время, рубрика, задача, формат, площадка и проверяющий.',
      stop: 'Если тема дублирует недавнюю публикацию — материал снимается с расписания до замены темы.',
    },
    {
      stage: 'В демо-среде, перед одобрением',
      what: 'Финальный человеческий контроль: тон, факты о клубе, уместность призыва к действию, корректность ссылки.',
      stop: 'Если редактор не подтверждает материал, статус возвращается в «черновик», публикация не выходит.',
    },
  ],

  statuses: ['идея', 'черновик', 'на проверке', 'готово к демо', 'одобрено'],
  agent_max_status: 'на проверке',
};

// --- CSV и markdown для файлов ----------------------------------------------
const header = ['Дата', 'Время', 'День недели', 'Рубрика', 'Задача', 'Тема', 'Формат', 'Площадка', 'Статус', 'Материал', 'Проверяющий'];
const csvLines = [header.join(';')];
rows.forEach(function (r) {
  csvLines.push([r.date, r.time, r.weekday, r.rubric, r.task, r.topic, r.format, r.platform, r.status, r.material, r.checker].join(';'));
});
const demo_csv = csvLines.join('\n');

const mdLines = [
  '| ' + header.join(' | ') + ' |',
  '|' + header.map(function () { return '---'; }).join('|') + '|',
];
rows.forEach(function (r) {
  mdLines.push('| ' + [r.date, r.time, r.weekday, r.rubric, r.task, r.topic, r.format, r.platform, r.status, r.material, r.checker].join(' | ') + ' |');
});
const demo_markdown = mdLines.join('\n');

return [{
  json: {
    demo_rows: rows,
    demo_csv: demo_csv,
    demo_markdown: demo_markdown,
    demo_scenario: demo_scenario,
    checklist: d.checklist,
    verdict: d.verdict,
    checks_passed: d.checks_passed,
    checks_total: d.checks_total,
    failed_checks: d.failed_checks,
    plan: d.plan,
    selected: d.selected,
    content: d.content,
    reels: d.reels,
    log_insights: d.log_insights,
    balance_comment: d.balance_comment,
    plan_start: d.plan_start,
    plan_end: d.plan_end,
  },
}];

// Узел «Подготовка файла (Markdown)».
// Операция write в узле «Read/Write Files from Disk» работает с бинарными данными,
// поэтому текст документа превращается в бинарный файл content-plan-<дата>.md.

const d = $json;
const fileName = 'content-plan-' + d.plan_start + '.md';

const bin = await helpers.prepareBinaryData(
  Buffer.from(d.document_md, 'utf8'),
  fileName,
  'text/markdown'
);

return [{
  json: {
    run_date: d.plan_start,
    file_name: fileName,
    document_chars: d.document_chars,
    verdict: d.verdict,
    checks_passed: d.checks_passed,
    checks_total: d.checks_total,
    document_md: d.document_md,
  },
  binary: { data: bin },
}];

// Узел «Подготовка файла (CSV)».
// Вторая запись на диск: расписание для демо-среды. Данные берутся из узла
// «Сборка итогового документа» напрямую — так узел не зависит от того, что
// предыдущий шаг уже перезаписал своё бинарное поле.

const d = $('Сборка итогового документа').first().json;
const fileName = 'demo-schedule-' + d.plan_start + '.csv';

const bin = await helpers.prepareBinaryData(
  Buffer.from(d.demo_csv, 'utf8'),
  fileName,
  'text/csv'
);

return [{
  json: {
    run_date: d.plan_start,
    file_name: fileName,
    demo_rows: (d.demo_rows || []).length,
    on_check: (d.demo_rows || []).filter(function (r) { return r.status === 'на проверке'; }).length,
    draft: (d.demo_rows || []).filter(function (r) { return r.status === 'черновик'; }).length,
    verdict: d.verdict,
    checks_passed: d.checks_passed,
    checks_total: d.checks_total,
  },
  binary: { data: bin },
}];

// Финальный узел: возвращает результат работы агента.
// Он же служит ответом при запуске по ссылке (Webhook).
const doc = $('Сборка итогового документа').first().json;
const csv = $('Подготовка файла (CSV)').first().json;
return [{ json: {
  status: 'ok',
  plan_period: doc.plan_start + ' — ' + doc.plan_end,
  publications: doc.plan.length,
  demo_rows: csv.demo_rows,
  demo_on_check: csv.on_check,
  demo_draft: csv.draft,
  verdict: doc.verdict,
  checks_passed: doc.checks_passed,
  checks_total: doc.checks_total,
  files: {
    plan_md: 'content-plan-' + doc.plan_start + '.md',
    demo_csv: 'demo-schedule-' + doc.plan_start + '.csv'
  },
  checklist: doc.checklist,
  // номер последней попытки: видно, сработал ли повтор
  attempts: {
    plan: $('Разбор контент-плана').last().json.attempt,
    content: $('Разбор контента').last().json.attempt
  },
  failed_checks: doc.failed_checks,
  checks: doc.checks,
  plan: doc.plan,
  document_md: doc.document_md
} }];
